import React, { useEffect, useState, useRef, useCallback } from 'react';
import { useOutletContext } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

/* ════════════════════════════════════════════════
   HELPERS
════════════════════════════════════════════════ */
function StatutBadge({ statut }) {
  const cfg = {
    en_attente: { bg: 'rgba(245,158,11,0.12)',  color: '#f59e0b', dot: '#f59e0b', label: 'En attente'  },
    confirmé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', dot: '#43e97b', label: 'Confirmé'    },
    refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', dot: '#ff6584', label: 'Refusé'      },
    annulé:     { bg: 'rgba(153,153,187,0.12)', color: '#9999bb', dot: '#9999bb', label: 'Annulé'      },
    terminé:    { bg: 'rgba(56,189,248,0.12)',  color: '#38bdf8', dot: '#38bdf8', label: 'Terminé'     },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', dot: 'var(--text2)', label: statut };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: '.72rem', fontWeight: 700, padding: '4px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: cfg.dot }} />
      {cfg.label}
    </span>
  );
}

function ModeBadge({ mode }) {
  if (mode === 'en_ligne') return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: 'rgba(56,189,248,0.1)', color: '#38bdf8' }}>🌐 En ligne</span>
  );
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: 'rgba(67,233,123,0.1)', color: '#43e97b' }}>🏫 Présentiel</span>
  );
}

function Avatar({ nom, size = 40 }) {
  const initials = (nom || 'E').split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);
  return (
    <div style={{ width: size, height: size, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: size * 0.35, fontWeight: 700, color: '#fff', flexShrink: 0 }}>
      {initials}
    </div>
  );
}

function formatDate(str) {
  if (!str) return '—';
  return new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
}

function formatMsgTime(str) {
  if (!str) return '';
  const d    = new Date(str);
  const diff = Math.floor((new Date() - d) / 1000);
  if (diff < 60)    return 'À l\'instant';
  if (diff < 3600)  return `${Math.floor(diff / 60)} min`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h`;
  return d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
}

/* ════════════════════════════════════════════════
   FENÊTRE CHAT — pour le professeur
════════════════════════════════════════════════ */
function ChatWindow({ reservation, currentUser, onClose }) {
  const [messages, setMessages]   = useState([]);
  const [input, setInput]         = useState('');
  const [sending, setSending]     = useState(false);
  const [uploading, setUploading] = useState(false);
  const bottomRef = useRef(null);
  const fileRef   = useRef(null);
  const pollRef   = useRef(null);

  const etudiantNom = reservation.etudiant_nom || 'Étudiant';

  const loadMessages = useCallback(async () => {
    try {
      const res = await api.get(`/api/messages/reservation/${reservation.id}`);
      setMessages(res.data);
    } catch { /* silencieux */ }
  }, [reservation.id]);

  useEffect(() => {
    loadMessages();
    pollRef.current = setInterval(loadMessages, 3000);
    return () => clearInterval(pollRef.current);
  }, [loadMessages]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendText = async () => {
    if (!input.trim() || sending) return;
    setSending(true);
    try {
      const res = await api.post(`/api/messages/reservation/${reservation.id}`, { contenu: input.trim() });
      setMessages(prev => [...prev, res.data]);
      setInput('');
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSending(false);
    }
  };

  const sendFile = async (file) => {
    if (!file) return;
    setUploading(true);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await api.post(
        `/api/messages/reservation/${reservation.id}/fichier`,
        fd,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );
      setMessages(prev => [...prev, res.data]);
    } catch (e) {
      alert('Erreur upload : ' + (e.response?.data?.detail || e.message));
    } finally {
      setUploading(false);
    }
  };

  const handleKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendText(); }
  };

  const renderFile = (msg) => {
    const url = `http://localhost:8001${msg.fichier_url}`;
    if (msg.fichier_type === 'image') {
      return (
        <a href={url} target="_blank" rel="noreferrer">
          <img src={url} alt={msg.fichier_nom} style={{ maxWidth: 200, maxHeight: 160, borderRadius: 10, display: 'block', objectFit: 'cover' }} />
        </a>
      );
    }
    return (
      <a href={url} target="_blank" rel="noreferrer" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', background: 'rgba(255,255,255,0.08)', borderRadius: 10, textDecoration: 'none', color: 'inherit' }}>
        <span style={{ fontSize: '1.3rem' }}>{msg.fichier_type === 'pdf' ? '📄' : '📎'}</span>
        <div>
          <div style={{ fontWeight: 600, fontSize: '.8rem' }}>{msg.fichier_nom}</div>
          <div style={{ fontSize: '.7rem', opacity: .7 }}>Ouvrir →</div>
        </div>
      </a>
    );
  };

  const isMine = (msg) => msg.expediteur_id === currentUser.id;

  return (
    <div style={{
      position: 'fixed', bottom: 24, right: 24,
      width: 380, height: 540,
      background: 'var(--surface)', border: '1px solid var(--border)',
      borderRadius: 20, display: 'flex', flexDirection: 'column',
      boxShadow: '0 24px 80px rgba(0,0,0,0.5)', zIndex: 2000,
      animation: 'chatIn .3s cubic-bezier(.34,1.56,.64,1)', overflow: 'hidden',
    }}>
      <style>{`@keyframes chatIn { from{opacity:0;transform:scale(.9) translateY(20px)} to{opacity:1;transform:scale(1) translateY(0)} }`}</style>

      {/* Header */}
      <div style={{ padding: '13px 16px', background: 'linear-gradient(135deg,rgba(108,99,255,.25),rgba(255,101,132,.15))', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: 10 }}>
        <Avatar nom={etudiantNom} size={38} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '.9rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{etudiantNom}</div>
          <div style={{ fontSize: '.7rem', color: 'var(--text2)', display: 'flex', alignItems: 'center', gap: 6 }}>
            <span>📅 {formatDate(reservation.date_cours)}</span>
            <ModeBadge mode={reservation.mode_seance} />
          </div>
        </div>
        <button onClick={onClose} style={{ width: 28, height: 28, borderRadius: 8, background: 'rgba(255,255,255,0.1)', border: 'none', cursor: 'pointer', color: 'var(--text)', fontSize: '.9rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
      </div>

      {/* Infos réservation compactes */}
      <div style={{ padding: '8px 14px', background: 'var(--surface2)', borderBottom: '1px solid var(--border)', display: 'flex', gap: 12, fontSize: '.74rem', color: 'var(--text2)' }}>
        {reservation.etudiant_email && <a href={`mailto:${reservation.etudiant_email}`} style={{ color: '#6c63ff', textDecoration: 'none' }}>✉️ {reservation.etudiant_email}</a>}
        {reservation.etudiant_telephone && <a href={`tel:${reservation.etudiant_telephone}`} style={{ color: '#6c63ff', textDecoration: 'none' }}>📞 {reservation.etudiant_telephone}</a>}
        <span>🕒 {String(reservation.heure_debut || '').slice(0,5)}–{String(reservation.heure_fin || '').slice(0,5)}</span>
      </div>

      {/* Messages */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '12px 12px 4px', display: 'flex', flexDirection: 'column', gap: 8 }}>
        {messages.length === 0 && (
          <div style={{ textAlign: 'center', padding: '24px 12px', color: 'var(--text2)' }}>
            <div style={{ fontSize: '1.8rem', marginBottom: 6 }}>💬</div>
            <div style={{ fontSize: '.8rem' }}>Démarrez la conversation.</div>
          </div>
        )}
        {messages.map(msg => {
          const mine = isMine(msg);
          return (
            <div key={msg.id} style={{ display: 'flex', flexDirection: mine ? 'row-reverse' : 'row', alignItems: 'flex-end', gap: 7 }}>
              {!mine && <Avatar nom={msg.expediteur_nom} size={24} />}
              <div style={{ maxWidth: '72%' }}>
                <div style={{ padding: msg.fichier_url ? '5px' : '8px 12px', borderRadius: mine ? '16px 16px 4px 16px' : '16px 16px 16px 4px', background: mine ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'var(--surface2)', color: mine ? '#fff' : 'var(--text)', fontSize: '.84rem', lineHeight: 1.5, border: mine ? 'none' : '1px solid var(--border)' }}>
                  {msg.contenu && <span>{msg.contenu}</span>}
                  {msg.fichier_url && renderFile(msg)}
                </div>
                <div style={{ fontSize: '.63rem', color: 'var(--text2)', marginTop: 2, textAlign: mine ? 'right' : 'left' }}>
                  {formatMsgTime(msg.created_at)}
                  {mine && <span style={{ marginLeft: 4 }}>{msg.lu ? ' ✓✓' : ' ✓'}</span>}
                </div>
              </div>
            </div>
          );
        })}
        <div ref={bottomRef} />
      </div>

      {/* Saisie */}
      <div style={{ padding: '9px 11px', borderTop: '1px solid var(--border)', display: 'flex', alignItems: 'flex-end', gap: 7 }}>
        <button onClick={() => fileRef.current?.click()} disabled={uploading} style={{ width: 34, height: 34, borderRadius: 9, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: uploading ? 'not-allowed' : 'pointer', color: 'var(--text2)', fontSize: '.95rem', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }} title="Envoyer un fichier">
          {uploading ? '⏳' : '📎'}
        </button>
        <input ref={fileRef} type="file" hidden accept="image/*,.pdf,.doc,.docx,.txt" onChange={e => sendFile(e.target.files[0])} />
        <textarea rows={1} value={input} onChange={e => setInput(e.target.value)} onKeyDown={handleKey} placeholder="Votre message..." style={{ flex: 1, background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 11, padding: '8px 11px', color: 'var(--text)', fontSize: '.84rem', resize: 'none', outline: 'none', maxHeight: 80, overflowY: 'auto', fontFamily: 'inherit' }} />
        <button onClick={sendText} disabled={!input.trim() || sending} style={{ width: 34, height: 34, borderRadius: 9, border: 'none', cursor: (!input.trim() || sending) ? 'not-allowed' : 'pointer', background: (!input.trim() || sending) ? 'var(--surface2)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', fontSize: '.95rem', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, transition: 'all .2s' }}>
          {sending ? '⏳' : '➤'}
        </button>
      </div>
    </div>
  );
}

