              {unreadCount > 0 && (
                <span style={{ position: 'absolute', top: -5, right: -5, background: '#ff6584', color: '#fff', fontSize: '.58rem', fontWeight: 800, padding: '1px 5px', borderRadius: 20, border: '1px solid var(--surface2)' }}>
                  {unreadCount}
