            <>
              <button onClick={() => onAction(r.id, 'confirmé')} style={{ padding: '7px 11px', background: 'rgba(67,233,123,0.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,0.3)', borderRadius: 8, cursor: 'pointer', fontSize: '.77rem', fontWeight: 700 }}>✅</button>
              <button onClick={() => onAction(r.id, 'refusé')}  style={{ padding: '7px 11px', background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 8, cursor: 'pointer', fontSize: '.77rem', fontWeight: 700 }}>❌</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   PAGE PRINCIPALE — DASHBOARD PROF
════════════════════════════════════════════════ */
export default function ProfDashboard() {
  const { user }  = useAuth();
  const outletCtx = useOutletContext?.() || {};
  const { chatResaId, setChatResaId } = outletCtx;

  const [reservations, setReservations] = useState([]);
  const [profile, setProfile]           = useState(null);
  const [loading, setLoading]           = useState(true);
  const [selectedResa, setSelectedResa] = useState(null);
  const [chatResa, setChatResa]         = useState(null);
  const [activeTab, setActiveTab]       = useState('en_attente');
  const [unreadMap, setUnreadMap]       = useState({});

  useEffect(() => {
    Promise.all([
      api.get('/api/reservations/mes-reservations').catch(() => ({ data: [] })),
      api.get('/api/professeurs/me').catch(() => ({ data: null })),
    ]).then(([resResa, resProf]) => {
      setReservations(resResa.data ?? []);
      setProfile(resProf.data ?? null);
      setLoading(false);
    });
    loadUnread();
    const interval = setInterval(loadUnread, 10000);
    return () => clearInterval(interval);
  }, []);

  // Si navigation depuis une notif de message → ouvrir le chat de la bonne réservation
  useEffect(() => {
    if (chatResaId && reservations.length > 0) {
      const resa = reservations.find(r => r.id === chatResaId);
      if (resa) {
        setChatResa(resa);
        setChatResaId?.(null);
      }
    }
  }, [chatResaId, reservations]);

  const loadUnread = async () => {
    try {
      const res = await api.get('/api/messages/non-lus');
      const map = {};
      (res.data.messages || []).forEach(m => {
        map[m.reservation_id] = (map[m.reservation_id] || 0) + 1;
      });
      setUnreadMap(map);
    } catch { /* silencieux */ }
  };

  async function updateReservation(id, statut) {
    try {
      await api.put(`/api/reservations/${id}`, { statut });
      setReservations(prev => prev.map(r => r.id === id ? { ...r, statut } : r));
    } catch {
      alert('Erreur lors de la mise à jour');
    }
  }

  const tabs = [
    { key: 'en_attente', label: 'En attente',  color: '#f59e0b' },
    { key: 'confirmé',   label: 'Confirmées',  color: '#43e97b' },
    { key: 'refusé',     label: 'Refusées',    color: '#ff6584' },
    { key: 'all',        label: 'Toutes',      color: '#6c63ff' },
  ];

  const filtered = activeTab === 'all'
    ? reservations
    : reservations.filter(r => r.statut === activeTab);

  const counts = {
    en_attente: reservations.filter(r => r.statut === 'en_attente').length,
    confirmé:   reservations.filter(r => r.statut === 'confirmé').length,
    refusé:     reservations.filter(r => r.statut === 'refusé').length,
    all:        reservations.length,
  };

  const totalUnread = Object.values(unreadMap).reduce((a, b) => a + b, 0);

  const statCards = [
    { icon: '📅', val: reservations.length,                              lbl: 'Réservations totales', color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
    { icon: '⏳', val: counts.en_attente,                                lbl: 'En attente',           color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
    { icon: '✅', val: counts.confirmé,                                   lbl: 'Confirmées',           color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
    { icon: '💬', val: totalUnread,                                       lbl: 'Msgs non lus',         color: '#ff6584', bg: 'rgba(255,101,132,.1)' },
    { icon: '⭐', val: parseFloat(profile?.note_moyenne || 0).toFixed(1), lbl: 'Note moyenne',         color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
  ];

  return (
    <div style={{ padding: 32, maxWidth: 1100, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ marginBottom: 28 }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.6rem', marginBottom: 4 }}>
          Bonjour, {user?.prenom} 👨‍🏫
        </div>
        <div style={{ color: 'var(--text2)', fontSize: '.9rem' }}>Voici un aperçu de votre activité</div>
      </div>

      {/* STAT CARDS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 16, marginBottom: 28 }}>
        {statCards.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 18px', display: 'flex', alignItems: 'center', gap: 13 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', flexShrink: 0 }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontSize: '1.6rem', fontWeight: 800, color: s.color, lineHeight: 1 }}>{s.val}</div>
              <div style={{ fontSize: '.74rem', color: 'var(--text2)', marginTop: 3 }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ALERTE messages non lus */}
      {totalUnread > 0 && (
        <div style={{ marginBottom: 20, padding: '12px 18px', background: 'rgba(108,99,255,0.07)', border: '1px solid rgba(108,99,255,0.25)', borderRadius: 14, display: 'flex', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: '1.2rem' }}>💬</span>
          <div style={{ flex: 1 }}>
            <span style={{ fontWeight: 700, color: '#6c63ff' }}>
              {totalUnread} message{totalUnread > 1 ? 's' : ''} non lu{totalUnread > 1 ? 's' : ''}
            </span>
            <span style={{ color: 'var(--text2)', fontSize: '.82rem' }}> de vos étudiants</span>
          </div>
          <button
            onClick={() => setActiveTab('confirmé')}
            style={{ padding: '6px 13px', background: 'rgba(108,99,255,0.15)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.3)', borderRadius: 9, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem' }}
          >
            Voir les chats →
          </button>
        </div>
      )}

      {/* ALERTE en attente */}
      {counts.en_attente > 0 && (
        <div style={{ marginBottom: 20, padding: '12px 18px', background: 'rgba(245,158,11,0.07)', border: '1px solid rgba(245,158,11,0.25)', borderRadius: 14, display: 'flex', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: '1.2rem' }}>🔔</span>
          <div style={{ flex: 1 }}>
            <span style={{ fontWeight: 700, color: '#f59e0b' }}>
              {counts.en_attente} demande{counts.en_attente > 1 ? 's' : ''} en attente de réponse
            </span>
            <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 2 }}>Répondez rapidement pour ne pas faire attendre vos étudiants.</div>
          </div>
          <button onClick={() => setActiveTab('en_attente')} style={{ padding: '6px 13px', background: 'rgba(245,158,11,0.15)', color: '#f59e0b', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 9, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem' }}>
            Traiter →
          </button>
        </div>
      )}

      {/* SECTION RÉSERVATIONS */}
      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 26 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 18 }}>
          <div>
            <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1.1rem' }}>📩 Demandes de réservation</h3>
            <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 3 }}>Gérez et répondez aux demandes de vos étudiants</div>
          </div>
        </div>

        {/* Onglets */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 18, borderBottom: '1px solid var(--border)', paddingBottom: 14, flexWrap: 'wrap' }}>
          {tabs.map(t => (
            <button key={t.key} onClick={() => setActiveTab(t.key)} style={{ padding: '7px 14px', borderRadius: 20, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem', transition: 'all .2s', border: activeTab === t.key ? `1px solid ${t.color}` : '1px solid var(--border)', background: activeTab === t.key ? `${t.color}20` : 'var(--surface2)', color: activeTab === t.key ? t.color : 'var(--text2)', display: 'flex', alignItems: 'center', gap: 6 }}>
              {t.label}
              <span style={{ background: activeTab === t.key ? t.color : 'var(--border)', color: activeTab === t.key ? '#000' : 'var(--text2)', fontSize: '.65rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20 }}>
                {counts[t.key]}
              </span>
            </button>
          ))}
        </div>

        {/* Liste */}
        {loading ? (
          <div style={{ padding: 40, textAlign: 'center', color: 'var(--text2)' }}>⏳ Chargement...</div>
        ) : filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '50px 20px', color: 'var(--text2)' }}>
            <div style={{ fontSize: '2.5rem', marginBottom: 12 }}>{activeTab === 'en_attente' ? '✅' : '📭'}</div>
            <div style={{ fontWeight: 600 }}>
              {activeTab === 'en_attente' ? 'Aucune demande en attente' : 'Aucune réservation'}
            </div>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {filtered
              .sort((a, b) => {
                if (a.statut === 'en_attente' && b.statut !== 'en_attente') return -1;
                if (b.statut === 'en_attente' && a.statut !== 'en_attente') return 1;
                return new Date(b.created_at || 0) - new Date(a.created_at || 0);
              })
              .map(r => (
                <ReservationCard
                  key={r.id}
                  r={r}
                  onView={setSelectedResa}
                  onAction={updateReservation}
                  onChat={resa => setChatResa(resa)}
                  unreadCount={unreadMap[r.id] || 0}
                />
              ))}
          </div>
        )}
      </div>

      {/* MODAL DÉTAIL */}
      {selectedResa && (
        <ReservationModal
          reservation={selectedResa}
          onClose={() => setSelectedResa(null)}
          onAction={(id, statut) => {
            updateReservation(id, statut);
            setSelectedResa(prev => prev ? { ...prev, statut } : null);
          }}
          onChat={resa => { setSelectedResa(null); setChatResa(resa); }}
        />
      )}

      {/* FENÊTRE CHAT */}
      {chatResa && (
        <ChatWindow
          reservation={chatResa}
          currentUser={user}
          onClose={() => { setChatResa(null); loadUnread(); }}
        />
      )}
    </div>
  );
}
